const item = $input.first().json;
const platform = item.platform || 'instagram';
const format = item.format || 'imagen_copy';

// Ideogram aspect ratios (Ideogram API soporta SOLO valores discretos).
// Política producción: ASPECT_3_4 (0.75) — Ideogram no soporta 4:5 (0.80).
// compose-image.js resizea de 3:4 → 4:5 final (1080x1350) con cover position 'top',
// cropeando los ~90px sobrantes del bottom (zona calma reservada por el Auditor).
// Resultado final en disco: 4:5 perfecto para cross-post IG/FB/LinkedIn.
// Reels mantienen 9:16 (formato vertical específico de IG, no cross-post).
const map = {
  'linkedin:imagen_copy': 'ASPECT_3_4',
  'linkedin:texto_largo': 'ASPECT_3_4',
  'linkedin:carrusel':   'ASPECT_3_4',
  'instagram:imagen_copy': 'ASPECT_3_4',
  'instagram:carrusel':   'ASPECT_3_4',
  'instagram:reel':       'ASPECT_9_16',
  'meta:imagen_copy':     'ASPECT_3_4',
  'meta:carrusel':        'ASPECT_3_4',
  'facebook:imagen_copy': 'ASPECT_3_4',
};

const key = `${platform}:${format}`;
const aspect_ratio = map[key] || 'ASPECT_3_4';

return [{ json: { ...item, aspect_ratio } }];

const item = $input.first().json;
const pillar = (item.pillar || '').toLowerCase();

const variants = {
