    'A mid-40s Latino man in a well-fitted suit walks purposefully through a modern glass atrium. Motion-blurred background, sharp subject, strong architectural lines.',
    'A Latina CEO in professional attire stands at a glass building entrance, sunrise reflected in the facade, briefcase in hand. Aspirational editorial photography.',
    'Wide aerial dawn shot of a modern Latin American city skyline, one warmly lit office window glowing in a high-rise tower. Symbolic, expansive, quiet ambition.',
    'A Latino professional in his 30s in business casual stands on a hilltop overlook, cityscape below, symbolic elevation. Natural warm light, cinematic shallow DOF.',
    'Dramatic silhouette of a confident business professional against a vivid orange-pink sunset sky, suspension bridge and city behind. Aspirational and dynamic.',
    'A Latina entrepreneur in her 30s stands at a harbor at dusk, calm water with city reflections, looking forward confidently. Peaceful, accomplished, elegant.'
  ]
};

const pillarMap = {
  educacion: 'educacion', experto: 'educacion', conocimiento: 'educacion',
  social_proof: 'social_proof', casos: 'social_proof', testimonial: 'social_proof', casos_de_uso: 'social_proof', prueba_social: 'social_proof',
  produccion: 'produccion', behind_scenes: 'produccion', proceso: 'produccion', herramienta: 'produccion', behind_the_scenes: 'produccion',
  promesa: 'promesa', vision: 'promesa', aspiracion: 'promesa'
};

const key = pillarMap[pillar] || 'educacion';
const pool = variants[key];
const scene = pool[Math.floor(Math.random() * pool.length)];

const systemPrompt = `You are a senior art director for B2B SaaS brand JAAGSOLUTIONS (an agency that builds automation systems for Latin American SMEs). Your job is to transform a generic image idea into a rich, production-quality prompt for Ideogram V_2.\n\nCRITICAL RULES:\n\n1. ABSOLUTELY NO TEXT, LETTERS, NUMBERS, WORDS, OR TYPOGRAPHY IN THE IMAGE. The image must be 100% text-free. No watermarks, no captions, no labels, no signage with readable words, no books with readable text, no screens showing readable text. The text overlay is added separately by post-processing.\n\n2. COMPOSITION MUST RESERVE NEGATIVE SPACE for a text overlay covering the BOTTOM 38% of the frame. The main subject and visual interest must be in the TOP 62%. The bottom area should be visually calm (sky, plain wall, gradient, soft bokeh, table surface) so dark text on a translucent overlay reads clearly.\n\n2b. HANDS AND ANATOMY (CRITICAL): Hands must NEVER appear in the foreground or be a prominent visual element. NEVER show close-up hands, pointing fingers, hands holding objects, pens, or pencils in the foreground. Strongly prefer compositions where hands are completely out of frame, hidden behind the body, or only barely visible at chest height far from camera. Frame people from the shoulders up or from behind.\n\n2c. PEOPLE COUNT (CRITICAL): If people appear, there must be a MINIMUM of 3 people — NEVER 2 people alone. Two-person compositions ALWAYS read as romantic regardless of intent. Preferred count: 3 to 5 people. Show them from the side, from behind, or from overhead — NEVER two people facing each other.\n\n2d. VISUAL PROTAGONIST (CRITICAL): The workflow diagram, process board, abstract flow lines, or meeting table MUST be the dominant visual element occupying at least half the frame. People are background observers looking AT the process — they are NOT the main subject.\n\n3. BRAND MOOD: confident, modern, clean, technological but human. Color palette leans cool (deep navy blues, slate, off-white) with optional warm accent. Lighting: soft, natural, professional.\n\n4. BASE SCENE — use this as your creative starting point and enrich it:\n   "${scene}"\n\n5. STYLE DESCRIPTORS to include: "professional editorial photography", "cinematic lighting", "shallow depth of field", "ultra-detailed", "high-end commercial style", "soft natural light", "color grading slightly cool with warm highlights".\n\n6. NEGATIVE INSTRUCTIONS to include: "no text, no letters, no logos, no watermarks, no captions, no signage, no readable typography, no numbers, no close-up hands, no pointing fingers, no handshakes, no deformed hands, no extra fingers, no romantic poses, no couple scenes, no intimate framing, no two people facing each other romantically, no seductive or flirtatious composition, no two-person composition, no hands in foreground, no close-up hands, no pens or objects held in foreground, minimum three people if people appear".\n\n7. ETHNICITY: prefer Latino / Hispanic subjects. Diverse but always plausibly Latin American.\n\n8. LENGTH: 90-160 words. Concrete, sensory, no fluff.\n\n9. OUTPUT FORMAT: return ONLY the final prompt in English, single paragraph, no preamble, no quotes, no explanation.`;

return [{ json: { ...item, auditor_system_prompt: systemPrompt, scene_variant: scene } }];

const auditResp = $input.first().json;
const prev = $('Calcular aspect_ratio').first().json;
const refined = auditResp.choices?.[0]?.message?.content?.trim();
if (!refined) {
  console.log('[Auditor] No refined prompt returned, using original');
  return [{ json: prev }];
}
console.log('[Auditor] Original:', prev.image_prompt);
console.log('[Auditor] Refined:', refined);
return [{ json: { ...prev, image_prompt: refined, image_prompt_original: prev.image_prompt } }];

const fs = require('fs');
const ideogramResp = $input.first().json;
const prev = $('Calcular aspect_ratio').first().json;

const imageUrl = ideogramResp.data?.[0]?.url;
if (!imageUrl) {
  throw new Error('Ideogram no devolvió imagen: ' + JSON.stringify(ideogramResp).slice(0, 500));
}

// Ruta fija — evita expresiones en Execute Command que no se resuelven
const tmpPath = '/tmp/n8n_compose.json';
fs.writeFileSync(tmpPath, JSON.stringify({
  image_url: imageUrl,
  post_id: prev.id,
  copy_text: prev.copy_text,
  hashtags: prev.hashtags,
  platform: prev.platform,
  scheduled_date: prev.scheduled_date,
  aspect_ratio: prev.aspect_ratio,
  output_dir: '/opt/jaagsolutions/content',
}));

return [{ json: { ...prev, tmp_path: tmpPath } }];

const execResult = $input.first().json;
const prev = $('Preparar input compose').first().json;

const stdout = (execResult.stdout || '').trim();
if (!stdout) {
  const stderr = (execResult.stderr || '').trim();
  throw new Error('compose-image.js sin output. stderr: ' + stderr.slice(0, 1000));
}

let result;
try {
  result = JSON.parse(stdout);
} catch (e) {
  throw new Error('JSON inválido de compose-image.js: ' + stdout.slice(0, 500));
}

if (!result.image_url) {
  throw new Error('compose-image.js no retornó image_url. Output: ' + JSON.stringify(result).slice(0, 500));
}

return [{ json: { ...prev, image_url: result.image_url, image_path: result.image_path, image_base64: result.image_base64, composition_meta: result.composition_meta } }];

const postData = $('Componer imagen final (Sharp + SVG)').first().json;
const fs = require('fs');
// image_path es la ruta local en disco; image_url es la URL pública en content.jaagsolutions.com
const filePath = postData.image_path;
const fileBuffer = fs.readFileSync(filePath);
const base64 = fileBuffer.toString('base64');

return [{
  json: postData,
  binary: {
    photo: {
      data: base64,
      mimeType: 'image/jpeg',
      fileName: `${postData.id}.jpg`
    }
  }
}];

const https = require('https');
const prev = $input.first().json;
const MAX_ATTEMPTS = 6;

function httpsPost(hostname, path, body, extraHeaders) {
  return new Promise((resolve, reject) => {
    const bodyStr = JSON.stringify(body);
    const options = {
      hostname, path, method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(bodyStr), ...extraHeaders },
      timeout: 30000
    };
    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try { resolve(JSON.parse(data)); }
        catch (e) { reject(new Error('JSON invalido: ' + data.slice(0, 300))); }
      });
    });
    req.on('error', reject);
    req.on('timeout', () => { req.destroy(); reject(new Error('Request timeout')); });
    req.write(bodyStr);
    req.end();
  });
}

function safeFallbackPrompt(item) {
  const headline = (item.copy_text || '').split('\\n').find(Boolean) || 'JAAGSOLUTIONS automation workflow';
  return 'Professional editorial photo for JAAGSOLUTIONS, a B2B automation agency for Latin American SMEs. A large glass board with abstract colored workflow lines and circular nodes dominates the composition occupying most of the frame. Three Latino professionals stand around it from the side, all looking at the board, none facing each other. The process visualization is the protagonist. Modern warm office, soft natural light, premium business mood, calm empty lower area for overlay. No screens, no laptops, no keyboards, no documents, no sticky notes, no signage, no interface panels, no charts, no graphs, no letters, no numbers, no symbols, no logos, no typography, no hands in foreground. Visual theme:' + headline.slice(0, 80);
}

async function generateIdeogram(prompt, aspectRatio, safeMode) {
  const seed = Math.floor(Math.random() * 2147483647);
  const styleTypes = safeMode ? ['GENERAL', 'GENERAL', 'REALISTIC'] : ['REALISTIC', 'REALISTIC', 'GENERAL', 'GENERAL'];
  const styleType = styleTypes[Math.floor(Math.random() * styleTypes.length)];
  return httpsPost('api.ideogram.ai', '/generate', {
    image_request: {
      prompt, aspect_ratio: aspectRatio, model: 'V_2',
      magic_prompt_option: 'OFF', seed, style_type: styleType,
      negative_prompt: 'text, letters, numbers, words, watermark, logo, caption, label, sign, typography, readable text, signage, signature, written language, glyphs, symbols, interface, UI, screen, monitor, laptop, keyboard, notebook, document, paper, sticky notes, whiteboard, chart, graph, dashboard, brand names, store signs, product labels, background text, environmental signage, fake brand text, decorative lettering, deformed hands, mutated hands, extra fingers, missing fingers, fused fingers, malformed fingers, too many fingers, distorted hands, mangled hands, twisted fingers, poorly drawn hands, low quality hands, bad anatomy, extra limbs, malformed limbs, disfigured, plastic skin, uncanny valley, doll-like, cgi face, artificial skin, deformed face, distorted proportions, wax figure, overly smooth skin, lifeless eyes, romantic, couple, lovers, intimate pose, seductive, flirtatious, romantic gaze, two people facing each other romantically, date scene, kissing, embracing, romance, amorous, lovingly gazing, two people alone, pair of people, two person scene, hands in foreground, close up hands, pen in hand foreground, writing hand, finger pointing close up'
    }
  }, { 'Api-Key': $env.IDEOGRAM_API_KEY });
}

async function checkOCR(imageUrl) {
  try {
    const resp = await httpsPost(
      'vision.googleapis.com',
      `/v1/images:annotate?key=${$env.GOOGLE_VISION_API_KEY}`,
      { requests: [{ image: { source: { imageUri: imageUrl } }, features: [{ type: 'TEXT_DETECTION', maxResults: 10 }] }] },
      {}
    );
    const annotations = resp.responses?.[0]?.textAnnotations || [];
    const description = annotations[0]?.description || '';
    return { hasText: description.length > 2, detectedText: description.slice(0, 200) };
  } catch (err) {
    console.log('[OCR] Vision API error - fail open: ' + err.message);
    return { hasText: false, detectedText: '' };
  }
}

async function checkAnatomy(imageUrl) {
  if (!$env.OPENAI_API_KEY) return { bad: false, reason: 'no-key' };
  try {
    const resp = await httpsPost('api.openai.com', '/v1/chat/completions', {
      model: 'gpt-4o-mini', max_tokens: 80, temperature: 0,
      messages: [{ role: 'user', content: [
        { type: 'text', text: 'You are a strict QA reviewer for marketing photos. Inspect ONLY human anatomy. Reply with compact JSON {"bad":true,"reason":"..."} or {"bad":false,"reason":""}. Set bad=true ONLY if a visible human hand, finger, arm or face is clearly deformed: wrong number of fingers, fused, extra or missing fingers, twisted or malformed hands or limbs, or a distorted face. If there are no people, hands are not visible, or anatomy looks natural, set bad=false. Be conservative; only flag clear deformities.' },
        { type: 'image_url', image_url: { url: imageUrl } }
      ] }]
    }, { 'Authorization': 'Bearer ' + $env.OPENAI_API_KEY });
    const txt = resp.choices?.[0]?.message?.content || '';
    const m = txt.match(/\{[\s\S]*\}/);
    if (!m) return { bad: false, reason: 'no-json' };
    const verdict = JSON.parse(m[0]);
    return { bad: verdict.bad === true, reason: String(verdict.reason || '').slice(0, 120) };
  } catch (err) {
    console.log('[Anatomy] Vision API error - fail open: ' + err.message);
    return { bad: false, reason: 'api-error' };
  }
}

let cleanImageUrl = null;
let lastError = '';
let usedSafeFallback = false;

for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
  const safeMode = attempt >= 3;
  const prompt = safeMode ? safeFallbackPrompt(prev) : prev.image_prompt;
  usedSafeFallback = usedSafeFallback || safeMode;
  const resp = await generateIdeogram(prompt, prev.aspect_ratio, safeMode);
  const url = resp.data?.[0]?.url;
  if (!url) throw new Error('Ideogram sin URL en intento ' + attempt + ': ' + JSON.stringify(resp).slice(0, 300));
  const ocr = await checkOCR(url);
  if (ocr.hasText) {
    lastError = 'Intento ' + attempt + (safeMode ? ' fallback seguro' : '') + ': texto detectado - "' + ocr.detectedText.replace(/"/g, "'").slice(0, 100) + '"';
    console.log('[OCR] ' + lastError);
    continue;
  }
  const anatomy = await checkAnatomy(url);
  if (anatomy.bad) {
    lastError = 'Intento ' + attempt + (safeMode ? ' fallback seguro' : '') + ': anatomia deforme - "' + anatomy.reason.replace(/"/g, "'") + '"';
    console.log('[Anatomy] ' + lastError);
    continue;
  }
  cleanImageUrl = url;
  console.log('[QA] Intento ' + attempt + (safeMode ? ' fallback seguro' : '') + ': imagen limpia (texto + anatomia OK)');
  break;
}

if (cleanImageUrl) {
  return [{ json: { ...prev, data: [{ url: cleanImageUrl }], used_safe_fallback: usedSafeFallback } }];
}
return [{ json: { ...prev, ocr_error: true, used_safe_fallback: usedSafeFallback, ocr_error_log: 'QA ' + MAX_ATTEMPTS + ' intentos fallidos (texto/anatomia). Ultimo: ' + lastError } }];

const rows = $input.all().map(i => i.json);
if (!rows.length) return [];
const lines = rows.map(r => {
  const detail = r.error_log ? ' | ' + String(r.error_log).slice(0, 180) : '';
  return '- ' + r.scheduled_time + ' ' + (r.platform || '').toUpperCase() + ' ' + r.pillar + ' | ' + r.status + ' | ' + r.id + detail;
});
return [{ json: { text: 'ALERTA post-cron JAAGSOLUTIONS 08:15\nPosts de hoy atascados o con error:\n' + lines.join('\n') + '\n\nAccion: revisar content_plan / n8n executions antes de que se pierda la publicacion.' } }];
